import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"企业邮局","description":"","frontmatter":{},"headers":[],"relativePath":"guide/organizations.md","filePath":"guide/organizations.md","lastUpdated":0}`),a={name:`guide/organizations.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="企业邮局" tabindex="-1">企业邮局 <a class="header-anchor" href="#企业邮局" aria-label="Permalink to “企业邮局”">​</a></h1><h2 id="组织与角色" tabindex="-1">组织与角色 <a class="header-anchor" href="#组织与角色" aria-label="Permalink to “组织与角色”">​</a></h2><p>企业邮局把域名、成员、邮箱、套餐和品牌集中到一个组织中。</p><table tabindex="0"><thead><tr><th>角色</th><th>主要权限</th></tr></thead><tbody><tr><td>所有者</td><td>管理组织、订阅、成员和关键设置，可转移所有权</td></tr><tr><td>管理员</td><td>管理成员、域名和企业邮箱，权限受组织策略限制</td></tr><tr><td>成员</td><td>使用获分配的企业邮箱和组织资源</td></tr></tbody></table><p>移除成员前应先处理其邮箱、共享关系和仍在进行的业务。所有权转移是关键操作，接收人应先加入组织并确认账号可用。</p><h2 id="添加自有域名" tabindex="-1">添加自有域名 <a class="header-anchor" href="#添加自有域名" aria-label="Permalink to “添加自有域名”">​</a></h2><ol><li>在组织域名页添加域名。</li><li>按页面给出的值配置域名所有权验证记录。</li><li>配置 MX、SPF、DKIM 和 DMARC。</li><li>等待 DNS 生效后重新检查。</li><li>验证完成后创建企业邮箱。</li></ol><p>页面显示的记录值以当前组织配置为准，不要照抄其他域名的 DKIM 公钥或验证值。</p><h2 id="企业邮箱" tabindex="-1">企业邮箱 <a class="header-anchor" href="#企业邮箱" aria-label="Permalink to “企业邮箱”">​</a></h2><p>组织管理员可以创建、停用和管理企业邮箱。可创建数量和存储空间受当前企业套餐限制。停用邮箱前，应先导出或转交仍需保留的邮件。</p><h2 id="品牌设置" tabindex="-1">品牌设置 <a class="header-anchor" href="#品牌设置" aria-label="Permalink to “品牌设置”">​</a></h2><p>组织可以配置显示名称、Logo 和主色，用于组织相关界面和通知。上传 Logo 后若没有立即变化，请刷新缓存并确认文件格式和大小符合页面要求。</p><h2 id="发信通道" tabindex="-1">发信通道 <a class="header-anchor" href="#发信通道" aria-label="Permalink to “发信通道”">​</a></h2><p>企业域名可使用平台直接投递或经批准的自定义中继。中继密码属于敏感凭据，只能在组织管理页保存，不应写入文档或提交到 Git。</p><h2 id="套餐生命周期" tabindex="-1">套餐生命周期 <a class="header-anchor" href="#套餐生命周期" aria-label="Permalink to “套餐生命周期”">​</a></h2><p>组织订阅决定成员数、域名数、邮箱数和存储配额。取消通常在当前周期结束后生效；恢复订阅应在到期前完成。具体价格、周期和权益以套餐页实时显示为准。</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};